  const a = OrderedSet(['a', 'b']).remove('a');
  const b = OrderedSet(['b']);
  expect(a.size).toBe(1);
  expect(a.hashCode()).toBe(b.hashCode());
  expect(a.equals(b)).toBe(true);

  const c = OrderedSet(['a', 'b', 'c']).remove('b');
  const d = OrderedSet(['a', 'c']);
  expect(c.hashCode()).toBe(d.hashCode());
  expect(c.equals(d)).toBe(true);
  expect(d.equals(c)).toBe(true);

  const m1 = OrderedMap({ a: 'a', b: 'b' }).remove('a');
  const m2 = OrderedMap({ b: 'b' });
  expect(m1.hashCode()).toBe(m2.hashCode());
  expect(m1.equals(m2)).toBe(true);
});
